"use client";

import { useEffect, type RefObject } from "react";
import { effectFrameInterval } from "./effect-utils";

export type EffectEnvironment = {
  inView: boolean;
  visible: boolean;
  motion: boolean;
  finePointer: boolean;
};

/** Browser APIs are touched only by effects, never during an SSR render. */
export function watchEffectEnvironment(
  element: HTMLElement,
  notify: (environment: EffectEnvironment) => void,
) {
  const reduced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)")
      : null;
  const pointer =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(hover: hover) and (pointer: fine)")
      : null;
  const forced =
    typeof window.matchMedia === "function"
      ? window.matchMedia("(forced-colors: active)")
      : null;
  let disposed = false;
  let inView = false;

  const visible = () => {
    if (document.visibilityState === "hidden" || !element.isConnected)
      return false;
    const style = getComputedStyle(element);
    // checkVisibility checks the host box, but its own hidden content can still
    // leave that box visible while suppressing every decorative child.
    if (
      style.visibility === "hidden" ||
      style.visibility === "collapse" ||
      style.opacity === "0" ||
      style.contentVisibility === "hidden"
    )
      return false;
    if (typeof element.checkVisibility === "function") {
      return element.checkVisibility({
        checkOpacity: true,
        checkVisibilityCSS: true,
        contentVisibilityAuto: true,
      });
    }
    if (!element.getClientRects().length) return false;
    for (
      let ancestor: HTMLElement | null = element;
      ancestor;
      ancestor = ancestor.parentElement
    ) {
      const ancestorStyle = getComputedStyle(ancestor);
      if (
        ancestorStyle.opacity === "0" ||
        ancestorStyle.contentVisibility === "hidden"
      )
        return false;
    }
    return true;
  };

  const report = () => {
    if (disposed) return;
    notify({
      inView,
      visible: visible(),
      motion:
        reduced !== null &&
        !reduced.matches &&
        !forced?.matches &&
        (
          element.closest("[data-motion-level]") ?? document.documentElement
        ).getAttribute("data-motion-level") !== "off",
      finePointer: pointer?.matches ?? false,
    });
  };

  const observeMedia = (media: MediaQueryList | null) => {
    if (!media) return () => {};
    if (typeof media.addEventListener === "function") {
      media.addEventListener("change", report);
      return () => media.removeEventListener("change", report);
    }
    media.addListener(report);
    return () => media.removeListener(report);
  };
  const removeReduced = observeMedia(reduced);
  const removePointer = observeMedia(pointer);
  const removeForced = observeMedia(forced);
  document.addEventListener("visibilitychange", report);
  window.addEventListener("aureform:appearance-change", report);
  window.addEventListener("resize", report, { passive: true });

  // Observe only this element's ancestry, not every mutation in the document.
  // Ignore our own pointer variables, which otherwise retrigger the observer.
  const ownStyle = () =>
    Array.from(element.style)
      .filter((name) => !name.startsWith("--afx-"))
      .map(
        (name) =>
          `${name}:${element.style.getPropertyValue(name)}:${element.style.getPropertyPriority(name)}`,
      )
      .join(";");
  let previousStyle = ownStyle();
  const motionObserver =
    typeof MutationObserver !== "undefined"
      ? new MutationObserver((records) => {
          const nextStyle = ownStyle();
          const ownVariablesOnly =
            nextStyle === previousStyle &&
            records.every(
              (record) =>
                record.target === element && record.attributeName === "style",
            );
          previousStyle = nextStyle;
          if (!ownVariablesOnly) report();
        })
      : null;
  for (
    let ancestor: HTMLElement | null = element;
    ancestor;
    ancestor = ancestor.parentElement
  ) {
    motionObserver?.observe(ancestor, {
      attributes: true,
      attributeFilter: [
        "data-motion-level",
        "data-palette",
        "style",
        "class",
        "hidden",
        "open",
        "disabled",
      ],
    });
  }

  let intersection: IntersectionObserver | null = null;
  const measureView = () => {
    const bounds = element.getBoundingClientRect();
    inView =
      bounds.width > 0 &&
      bounds.height > 0 &&
      bounds.bottom > 0 &&
      bounds.right > 0 &&
      bounds.top < window.innerHeight &&
      bounds.left < window.innerWidth;
    report();
  };
  if (typeof IntersectionObserver !== "undefined") {
    intersection = new IntersectionObserver(
      ([entry]) => {
        inView = Boolean(entry?.isIntersecting && entry.intersectionRatio > 0);
        report();
      },
      { threshold: 0 },
    );
    intersection.observe(element);
  } else {
    // Old embedded browsers still pause offscreen without a polyfill.
    window.addEventListener("scroll", measureView, {
      passive: true,
      capture: true,
    });
    window.addEventListener("resize", measureView, { passive: true });
    measureView();
  }
  report();

  return () => {
    disposed = true;
    intersection?.disconnect();
    motionObserver?.disconnect();
    removeReduced();
    removePointer();
    removeForced();
    document.removeEventListener("visibilitychange", report);
    window.removeEventListener("aureform:appearance-change", report);
    window.removeEventListener("resize", report);
    window.removeEventListener("scroll", measureView, true);
    window.removeEventListener("resize", measureView);
  };
}

export function useEffectActivity(ref: RefObject<HTMLElement | null>) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    const remove = watchEffectEnvironment(element, (environment) => {
      element.dataset.afxMotion =
        environment.motion && environment.visible && environment.inView
          ? "running"
          : "paused";
    });
    return () => {
      remove();
      element.dataset.afxMotion = "paused";
    };
  }, [ref]);
}

const editingTarget =
  'input, textarea, select, [contenteditable]:not([contenteditable="false"]), [data-effect-static]';
const disabledTarget = ':disabled, [aria-disabled="true"], [data-disabled]';

/**
 * One frame-coalesced write per pointer update. Never captures a pointer,
 * cancels an event, changes touch-action, or installs a wheel handler.
 */
export function useEffectPointer(
  ref: RefObject<HTMLElement | null>,
  mode: "spotlight" | "tilt" | "magnetic",
  amount: number,
  limit: number,
) {
  useEffect(() => {
    const element = ref.current;
    if (!element) return;
    let environment: EffectEnvironment = {
      inView: false,
      visible: false,
      motion: false,
      finePointer: false,
    };
    let frame = 0;
    let lastWrite = -Infinity;
    let bounds: DOMRect | null = null;
    let point = { x: 0, y: 0 };

    const reset = () => {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      bounds = null;
      element.dataset.afxPointer = "idle";
      element.style.setProperty("--afx-pointer-x", "50%");
      element.style.setProperty("--afx-pointer-y", "35%");
      element.style.setProperty("--afx-rotate-x", "0deg");
      element.style.setProperty("--afx-rotate-y", "0deg");
      element.style.setProperty("--afx-magnetic-x", "0px");
      element.style.setProperty("--afx-magnetic-y", "0px");
    };

    const allowed = () =>
      environment.inView &&
      environment.visible &&
      environment.motion &&
      environment.finePointer &&
      !element.matches(disabledTarget) &&
      // Keep a focused control stationary for keyboard and mixed-input users.
      (mode === "spotlight" || !element.contains(document.activeElement));

    const write = (now: number) => {
      frame = 0;
      if (!allowed() || !bounds || !bounds.width || !bounds.height) {
        reset();
        return;
      }
      if (now - lastWrite < effectFrameInterval) {
        frame = requestAnimationFrame(write);
        return;
      }
      lastWrite = now;
      const x = Math.min(
        1,
        Math.max(0, (point.x - bounds.left) / bounds.width),
      );
      const y = Math.min(
        1,
        Math.max(0, (point.y - bounds.top) / bounds.height),
      );
      element.dataset.afxPointer = "active";
      element.style.setProperty("--afx-pointer-x", `${(x * 100).toFixed(2)}%`);
      element.style.setProperty("--afx-pointer-y", `${(y * 100).toFixed(2)}%`);
      if (mode === "tilt") {
        element.style.setProperty(
          "--afx-rotate-x",
          `${((0.5 - y) * amount * 2).toFixed(2)}deg`,
        );
        element.style.setProperty(
          "--afx-rotate-y",
          `${((x - 0.5) * amount * 2).toFixed(2)}deg`,
        );
      } else if (mode === "magnetic") {
        const dx = Math.min(
          limit,
          Math.max(-limit, (x - 0.5) * bounds.width * amount),
        );
        const dy = Math.min(
          limit,
          Math.max(-limit, (y - 0.5) * bounds.height * amount),
        );
        element.style.setProperty("--afx-magnetic-x", `${dx.toFixed(2)}px`);
        element.style.setProperty("--afx-magnetic-y", `${dy.toFixed(2)}px`);
      }
    };

    const move = (event: PointerEvent) => {
      if (
        !allowed() ||
        event.defaultPrevented ||
        event.buttons !== 0 ||
        !["mouse", "pen"].includes(event.pointerType) ||
        (event.target instanceof Element && event.target.closest(editingTarget))
      ) {
        reset();
        return;
      }
      // A stable entry rectangle prevents feedback from the element's transform.
      bounds ??= element.getBoundingClientRect();
      point = { x: event.clientX, y: event.clientY };
      if (!frame) frame = requestAnimationFrame(write);
    };
    const focus = () => reset();
    const removeEnvironment = watchEffectEnvironment(element, (next) => {
      environment = next;
      element.dataset.afxMotion =
        next.motion && next.inView && next.visible ? "running" : "paused";
      if (!allowed()) reset();
    });

    element.addEventListener("pointerenter", move, { passive: true });
    element.addEventListener("pointermove", move, { passive: true });
    element.addEventListener("pointerleave", reset, { passive: true });
    element.addEventListener("pointercancel", reset, { passive: true });
    element.addEventListener("pointerdown", reset, { passive: true });
    element.addEventListener("focusin", focus);
    window.addEventListener("scroll", reset, { passive: true, capture: true });
    window.addEventListener("resize", reset, { passive: true });

    // Native disabled/loading changes also settle an already active transform.
    const disabledObserver =
      typeof MutationObserver !== "undefined"
        ? new MutationObserver(() => {
            if (element.matches(disabledTarget)) reset();
          })
        : null;
    disabledObserver?.observe(element, {
      attributes: true,
      attributeFilter: ["disabled", "aria-disabled", "data-disabled"],
    });

    return () => {
      removeEnvironment();
      disabledObserver?.disconnect();
      element.removeEventListener("pointerenter", move);
      element.removeEventListener("pointermove", move);
      element.removeEventListener("pointerleave", reset);
      element.removeEventListener("pointercancel", reset);
      element.removeEventListener("pointerdown", reset);
      element.removeEventListener("focusin", focus);
      window.removeEventListener("scroll", reset, true);
      window.removeEventListener("resize", reset);
      reset();
      element.dataset.afxMotion = "paused";
    };
  }, [ref, mode, amount, limit]);
}

import type { CSSProperties } from "react";

export const defaultEffectColors = ["#8b5cf6", "#22d3ee", "#34d399"] as const;
export const effectFrameRate = 30;
export const effectFrameInterval = 1000 / effectFrameRate;

export type EffectStyle = CSSProperties & {
  [key: `--afx-${string}`]: string | number;
};

export function boundedNumber(
  value: number | undefined,
  min: number,
  max: number,
  fallback: number,
) {
  return Number.isFinite(value)
    ? Math.min(max, Math.max(min, value as number))
    : fallback;
}

/** Missing palette entries retain the original violet/cyan/emerald palette. */
export function effectColors(colors?: string[]): [string, string, string] {
  return defaultEffectColors.map((fallback, index) => {
    const color = colors?.[index];
    const token = ["primary", "secondary", "tertiary"][index];
    return typeof color === "string" && color.trim()
      ? color.trim()
      : `var(--af-color-${token}, ${fallback})`;
  }) as [string, string, string];
}

export function paletteStyle(colors?: string[]): EffectStyle {
  const [a, b, c] = effectColors(colors);
  return { "--afx-color-a": a, "--afx-color-b": b, "--afx-color-c": c };
}

export type GradientKind = "linear" | "radial" | "mesh";
export type ShaderKind = "aurora" | "waves" | "iridescent" | "none";

export function gradientField(
  kind: GradientKind,
  colors?: string[],
  angle = 135,
) {
  const [a, b, c] = effectColors(colors);
  const degrees = boundedNumber(angle, -3600, 3600, 135);

  if (kind === "linear") {
    return `linear-gradient(${degrees}deg, ${a} 0%, ${b} 52%, ${c} 100%)`;
  }
  if (kind === "radial") {
    return `radial-gradient(ellipse at 72% 28%, ${c} 0%, ${b} 36%, ${a} 72%, #090a16 100%)`;
  }
  return [
    `radial-gradient(ellipse at 82% 18%, ${c} 0%, transparent 46%)`,
    `radial-gradient(ellipse at 68% 78%, ${b} 0%, transparent 55%)`,
    `radial-gradient(ellipse at 15% 24%, ${a} 0%, transparent 62%)`,
    "linear-gradient(135deg, #161027, #090e1d)",
  ].join(", ");
}

/*
 * Colocated, importable mechanics. Every selector is effects-owned; no
 * AppearanceProvider, global effects stylesheet or generated token is needed.
 */
@property --afx-orbit {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes afx-border-orbit {
  to {
    --afx-orbit: 360deg;
  }
}

@layer components {
  .afx-background {
    position: relative;
    isolation: isolate;
    overflow: hidden;
    background-color: #090a16;
    color: #f8fafc;
  }

  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    user-select: none;
  }

  .afx-background-field {
    opacity: var(--afx-intensity, 0.55);
  }

  .afx-shader-canvas {
    display: block;
    opacity: 0;
    transition: opacity 400ms ease;
  }

  .afx-shader-canvas[data-ready="true"] {
    opacity: 1;
  }

  .afx-shader-canvas[data-ready="false"] {
    transition: none;
  }

  .afx-background-scrim {
    background:
      linear-gradient(90deg, rgb(9 10 22 / 62%), transparent 78%),
      linear-gradient(180deg, rgb(9 10 22 / 8%), rgb(9 10 22 / 48%));
  }

  .afx-background-content {
    position: relative;
    z-index: 1;
    height: 100%;
  }

  .afx-surface {
    position: relative;
    isolation: isolate;
    border-radius: var(--af-radius, 1.25rem);
    border: 1px solid var(--border, rgb(139 92 246 / 20%));
    background-color: var(--surface, #11111f);
    color: var(--foreground, #f8fafc);
    box-shadow: 0 16px 48px -24px rgb(10 8 30 / 42%);
  }

  .afx-spotlight::before,
  .afx-tilt::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    pointer-events: none;
    background: radial-gradient(
      circle var(--afx-spotlight-radius, 320px) at var(--afx-pointer-x, 50%)
        var(--afx-pointer-y, 35%),
      color-mix(
          in srgb,
          var(--afx-spotlight-color, #8b5cf6)
            calc(var(--afx-spotlight-intensity, 0.2) * 100%),
          transparent
        )
        0%,
      transparent 75%
    );
    opacity: 0.65;
    transition: opacity 180ms ease;
  }

  .afx-spotlight[data-afx-pointer="active"]::before,
  .afx-tilt[data-afx-pointer="active"]::before {
    opacity: 1;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    content: "";
    position: absolute;
    inset: -1px;
    border-radius: inherit;
    padding: var(--afx-border-width, 1px);
    pointer-events: none;
    background: conic-gradient(
      from var(--afx-orbit),
      var(--afx-color-a, #8b5cf6),
      var(--afx-color-b, #22d3ee) 28%,
      var(--afx-color-c, #34d399) 48%,
      transparent 63%,
      var(--afx-color-a, #8b5cf6) 84%,
      var(--afx-color-b, #22d3ee)
    );
    -webkit-mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    mask:
      linear-gradient(#fff 0 0) content-box,
      linear-gradient(#fff 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
    animation: afx-border-orbit var(--afx-border-duration, 12s)
      steps(var(--afx-border-steps, 360), end) infinite;
    animation-play-state: paused;
  }

  .afx-glow-border::before {
    opacity: 0.9;
  }

  .afx-glow-border::after {
    inset: -3px;
    opacity: 0.32;
    filter: blur(5px);
  }

  .afx-glow-border[data-afx-motion="running"]::before,
  .afx-glow-border[data-afx-motion="running"]::after {
    animation-play-state: running;
  }

  .afx-tilt {
    transform: perspective(var(--afx-perspective, 900px))
      rotateX(var(--afx-rotate-x, 0deg)) rotateY(var(--afx-rotate-y, 0deg));
    transform-origin: center;
    transition: transform 180ms cubic-bezier(0.2, 0.7, 0.2, 1);
  }

  .afx-magnetic-button {
    position: relative;
    isolation: isolate;
    border: 1px solid rgb(255 255 255 / 18%);
    background: linear-gradient(
      120deg,
      color-mix(in srgb, var(--af-color-primary, #8b5cf6) 40%, #211938),
      #7044d8 58%,
      #3f59aa
    );
    color: #fff;
    box-shadow:
      inset 0 1px 0 rgb(255 255 255 / 16%),
      0 6px 24px -8px rgb(139 92 246 / 56%);
    transform: translate(
      var(--afx-magnetic-x, 0px),
      var(--afx-magnetic-y, 0px)
    );
    transition:
      transform 200ms cubic-bezier(0.2, 0.7, 0.2, 1),
      box-shadow 180ms ease;
    cursor: pointer;
  }

  .afx-magnetic-button:disabled,
  .afx-magnetic-button[aria-disabled="true"],
  .afx-magnetic-button[data-disabled] {
    opacity: 0.5;
    cursor: default;
    transform: none;
  }
}

/* Focus decoration is static and survives every motion preference. */
.afx-surface:focus-visible,
.afx-surface:has(:focus-visible),
.afx-magnetic-button:focus-visible {
  outline: 2px solid var(--ring, #22d3ee);
  outline-offset: 4px;
}

.afx-surface:focus-visible::before,
.afx-surface:has(:focus-visible)::before {
  opacity: 1;
}

.afx-tilt:focus-within,
.afx-magnetic-button:focus-within {
  transform: none;
}

@media (hover: none), (pointer: coarse) {
  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
    transition: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .afx-shader-canvas {
    opacity: 0 !important;
    transition: none;
  }

  .afx-tilt,
  .afx-magnetic-button {
    transform: none;
  }

  .afx-tilt,
  .afx-magnetic-button,
  .afx-spotlight::before,
  .afx-tilt::before {
    transition: none;
  }

  .afx-glow-border::before,
  .afx-glow-border::after {
    animation: none;
  }
}

[data-shader-state="off"] .afx-shader-canvas,
.afx-shader-canvas[data-shader-state="off"] {
  opacity: 0 !important;
  transition: none;
}

.afx-tilt[data-afx-motion="paused"],
.afx-magnetic-button[data-afx-motion="paused"] {
  transform: none;
  transition: none;
}

.afx-spotlight[data-afx-motion="paused"]::before,
.afx-tilt[data-afx-motion="paused"]::before {
  transition: none;
}

.afx-glow-border[data-afx-motion="paused"]::before,
.afx-glow-border[data-afx-motion="paused"]::after {
  animation-play-state: paused;
}

@media (forced-colors: active) {
  .afx-background-field,
  .afx-shader-canvas,
  .afx-background-scrim,
  .afx-spotlight::before,
  .afx-tilt::before,
  .afx-glow-border::before,
  .afx-glow-border::after {
    display: none;
  }

  .afx-background,
  .afx-surface,
  .afx-magnetic-button {
    background: Canvas;
    color: CanvasText;
    border: 1px solid ButtonText;
    box-shadow: none;
  }

  .afx-surface:focus-visible,
  .afx-surface:has(:focus-visible),
  .afx-magnetic-button:focus-visible {
    outline-color: Highlight;
  }
}

"use client";

import { useEffect, useMemo, useRef, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import {
  boundedNumber,
  effectColors,
  gradientField,
  type EffectStyle,
  type ShaderKind,
} from "./effect-utils";
import {
  watchEffectEnvironment,
  type EffectEnvironment,
} from "./effect-motion";
import type { ShaderConfig, ShaderRenderer } from "./shader-runtime";
import "./effects.css";

export type ShaderBackgroundProps = {
  kind?: ShaderKind;
  colors?: string[];
  speed?: number;
  scale?: number;
  intensity?: number;
  paused?: boolean;
  className?: string;
  children?: ReactNode;
};

export type ShaderState = "loading" | "running" | "paused" | "fallback" | "off";

export function ShaderBackground({
  kind = "aurora",
  colors,
  speed = 0.2,
  scale = 1,
  intensity = 0.55,
  paused = false,
  className,
  children,
}: ShaderBackgroundProps = {}) {
  const hostRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const controllerRef = useRef<{
    update: (config: ShaderConfig) => void;
  } | null>(null);
  const config = useMemo<ShaderConfig>(
    () => ({
      colors: effectColors(colors),
      speed: boundedNumber(speed, 0, 1, 0.2),
      scale: boundedNumber(scale, 0.25, 4, 1),
      intensity: boundedNumber(intensity, 0, 1, 0.55),
      paused,
    }),
    [colors, speed, scale, intensity, paused],
  );
  const configRef = useRef(config);

  // Uniform and pause updates do not recompile the program or reset time.
  useEffect(() => {
    configRef.current = config;
    controllerRef.current?.update(config);
  }, [config]);

  useEffect(() => {
    const host = hostRef.current;
    const canvasElement = canvasRef.current;
    if (!host) return;
    if (kind === "none" || !canvasElement) {
      host.dataset.shaderState = "off";
      host.dataset.shaderFrame = "0";
      return;
    }
    const canvas = canvasElement;

    let disposed = false;
    let loading = false;
    let unavailable = false;
    let lost = false;
    let frames = 0;
    let renderer: ShaderRenderer | null = null;
    let current = configRef.current;
    let environment: EffectEnvironment = {
      inView: false,
      visible: false,
      motion: false,
      finePointer: false,
    };
    let idle: number | null = null;
    let idleCallback = false;
    host.dataset.shaderFrame = "0";
    canvas.dataset.shaderFrame = "0";

    const state = (value: ShaderState) => {
      host.dataset.shaderState = value;
      canvas.dataset.shaderState = value;
    };
    const fallback = () => {
      canvas.dataset.ready = "false";
    };
    const canRun = () =>
      !disposed &&
      !lost &&
      environment.motion &&
      environment.inView &&
      environment.visible &&
      !current.paused &&
      current.speed > 0 &&
      current.intensity > 0;

    const cancelInitialization = () => {
      if (idle === null) return;
      if (idleCallback) window.cancelIdleCallback(idle);
      else window.clearTimeout(idle);
      idle = null;
      loading = false;
    };

    const initialize = async () => {
      idle = null;
      if (!canRun()) {
        loading = false;
        synchronize();
        return;
      }
      try {
        // Literal dynamic import is included by the registry dependency graph.
        const { createShaderRenderer } = await import("./shader-runtime");
        if (disposed) return;
        loading = false;
        if (!canRun()) {
          synchronize();
          return;
        }
        renderer = createShaderRenderer(canvas, host, kind, current, () => {
          frames += 1;
          host.dataset.shaderFrame = String(frames);
          canvas.dataset.shaderFrame = String(frames);
          canvas.dataset.ready = "true";
          state("running");
        });
        unavailable = renderer === null;
        synchronize();
      } catch {
        if (disposed) return;
        loading = false;
        unavailable = true;
        fallback();
        synchronize();
      }
    };

    function synchronize() {
      if (disposed) return;
      if (!canRun() || unavailable) cancelInitialization();
      renderer?.configure(current);
      if (!environment.motion || current.intensity === 0) {
        renderer?.stop();
        fallback();
        state("off");
      } else if (unavailable || lost) {
        renderer?.stop();
        fallback();
        state("fallback");
      } else if (!canRun()) {
        renderer?.stop();
        state("paused");
      } else if (renderer) {
        if (renderer.resize()) fallback();
        renderer.start();
        // A newly compiled canvas remains on the fallback until its first draw.
        state(canvas.dataset.ready === "true" ? "running" : "loading");
      } else if (!loading) {
        loading = true;
        state("loading");
        if (typeof window.requestIdleCallback === "function") {
          idleCallback = true;
          idle = window.requestIdleCallback(() => void initialize(), {
            timeout: 600,
          });
        } else {
          idle = window.setTimeout(() => void initialize(), 0);
        }
      } else {
        state("loading");
      }
    }

    const controller = {
      update(next: ShaderConfig) {
        current = next;
        synchronize();
      },
    };
    controllerRef.current = controller;

    const contextLost = (event: Event) => {
      // Permit restoration; the attractive CSS field remains underneath.
      event.preventDefault();
      lost = true;
      cancelInitialization();
      renderer?.dispose();
      renderer = null;
      fallback();
      state("fallback");
    };
    const contextRestored = () => {
      lost = false;
      unavailable = false;
      synchronize();
    };
    canvas.addEventListener("webglcontextlost", contextLost);
    canvas.addEventListener("webglcontextrestored", contextRestored);

    const removeEnvironment = watchEffectEnvironment(host, (next) => {
      environment = next;
      synchronize();
    });
    const resize = () => {
      if (!canRun()) return;
      if (renderer?.resize()) {
        // Dormant buffers retain their frame and resize when running resumes.
        fallback();
        state("loading");
      }
    };
    const resizeObserver =
      typeof ResizeObserver !== "undefined" ? new ResizeObserver(resize) : null;
    resizeObserver?.observe(host);
    window.addEventListener("resize", resize, { passive: true });

    return () => {
      disposed = true;
      cancelInitialization();
      removeEnvironment();
      resizeObserver?.disconnect();
      window.removeEventListener("resize", resize);
      canvas.removeEventListener("webglcontextlost", contextLost);
      canvas.removeEventListener("webglcontextrestored", contextRestored);
      renderer?.dispose();
      fallback();
      if (controllerRef.current === controller) controllerRef.current = null;
    };
  }, [kind]);

  const style: EffectStyle = { "--afx-intensity": config.intensity };
  return (
    <div
      ref={hostRef}
      data-slot="shader-background"
      data-shader-kind={kind}
      data-shader-state={kind === "none" ? "off" : "fallback"}
      data-shader-frame="0"
      className={cn("afx-background min-h-64 rounded-2xl", className)}
      style={style}
    >
      <div
        aria-hidden="true"
        className="afx-background-field"
        style={{ backgroundImage: gradientField("mesh", colors) }}
      />
      {kind !== "none" && (
        <canvas
          key={kind}
          ref={canvasRef}
          aria-hidden="true"
          role="presentation"
          width={1}
          height={1}
          data-shader-kind={kind}
          data-shader-state="fallback"
          data-shader-frame="0"
          data-ready="false"
          className="afx-shader-canvas"
        />
      )}
      <div aria-hidden="true" className="afx-background-scrim" />
      <div className="afx-background-content">{children}</div>
    </div>
  );
}

import {
  defaultEffectColors,
  effectFrameInterval,
  type ShaderKind,
} from "./effect-utils";
import { shaderFragmentSources, shaderVertexSource } from "./shaders";

export type ShaderConfig = {
  colors: [string, string, string];
  speed: number;
  scale: number;
  intensity: number;
  paused: boolean;
};

export type ShaderRenderer = {
  configure: (config: ShaderConfig) => void;
  resize: () => boolean;
  start: () => void;
  stop: () => void;
  dispose: () => void;
};

const pixelBudget = 1_300_000;
const maxDimension = 2048;

function compileShader(
  gl: WebGL2RenderingContext,
  type: number,
  source: string,
) {
  const shader = gl.createShader(type);
  if (!shader) throw new Error("Shader allocation failed.");
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    const reason = gl.getShaderInfoLog(shader);
    gl.deleteShader(shader);
    throw new Error(reason || "Shader compilation failed.");
  }
  return shader;
}

function readColors(host: HTMLElement, colors: ShaderConfig["colors"]) {
  const probe = document.createElement("span");
  probe.setAttribute("aria-hidden", "true");
  probe.style.display = "none";
  host.appendChild(probe);
  try {
    return colors.map((color, index) => {
      probe.style.color = defaultEffectColors[index];
      // Resolve CSS variables against the nearest AppearanceScope.
      if (CSS.supports("color", color)) probe.style.color = color;
      return getComputedStyle(probe).color;
    });
  } finally {
    probe.remove();
  }
}

/**
 * Small WebGL2 renderer with an owned program/VAO and no global ticker.
 * Callers create it only after visibility and motion checks have passed.
 */
export function createShaderRenderer(
  canvas: HTMLCanvasElement,
  host: HTMLElement,
  kind: Exclude<ShaderKind, "none">,
  initial: ShaderConfig,
  onFrame: () => void,
): ShaderRenderer | null {
  const gl = canvas.getContext("webgl2", {
    alpha: false,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
    preserveDrawingBuffer: false,
    powerPreference: "low-power",
  });
  if (!gl || gl.isContextLost()) return null;

  let vertex: WebGLShader | null = null;
  let fragment: WebGLShader | null = null;
  let program: WebGLProgram | null = null;
  let vertexArray: WebGLVertexArrayObject | null = null;

  try {
    vertex = compileShader(gl, gl.VERTEX_SHADER, shaderVertexSource);
    fragment = compileShader(
      gl,
      gl.FRAGMENT_SHADER,
      shaderFragmentSources[kind],
    );
    program = gl.createProgram();
    if (!program) throw new Error("Program allocation failed.");
    gl.attachShader(program, vertex);
    gl.attachShader(program, fragment);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      throw new Error(
        gl.getProgramInfoLog(program) || "Program linking failed.",
      );
    }
    vertexArray = gl.createVertexArray();
    if (!vertexArray) throw new Error("Vertex array allocation failed.");
  } catch (error) {
    if (vertex) gl.deleteShader(vertex);
    if (fragment) gl.deleteShader(fragment);
    if (program) gl.deleteProgram(program);
    if (vertexArray) gl.deleteVertexArray(vertexArray);
    throw error;
  }

  // Linked programs retain their code; the intermediate shaders are released.
  gl.detachShader(program, vertex);
  gl.detachShader(program, fragment);
  gl.deleteShader(vertex);
  gl.deleteShader(fragment);

  const uniforms = Object.fromEntries(
    [
      "uResolution",
      "uTime",
      "uScale",
      "uIntensity",
      "uColorA",
      "uColorB",
      "uColorC",
    ].map((name) => [name, gl.getUniformLocation(program, name)]),
  );
  gl.disable(gl.DEPTH_TEST);
  gl.disable(gl.BLEND);
  gl.disable(gl.CULL_FACE);

  const colorCanvas = document.createElement("canvas");
  colorCanvas.width = 1;
  colorCanvas.height = 1;
  const colorContext = colorCanvas.getContext("2d", {
    willReadFrequently: true,
  });
  let colorKey = "";
  let rgbColors = defaultEffectColors.map((color) =>
    [1, 3, 5].map(
      (offset) => parseInt(color.slice(offset, offset + 2), 16) / 255,
    ),
  );
  let config = initial;
  let disposed = false;
  let running = false;
  let frame = 0;
  let lastDraw = -1;
  let lastTick = 0;
  let phase = 0;

  const configure = (next: ShaderConfig) => {
    config = next;
    const resolved = readColors(host, next.colors);
    const key = resolved.join("|");
    if (key === colorKey || !colorContext) return;
    colorKey = key;
    rgbColors = resolved.map((color) => {
      colorContext.clearRect(0, 0, 1, 1);
      colorContext.fillStyle = color;
      colorContext.fillRect(0, 0, 1, 1);
      return Array.from(colorContext.getImageData(0, 0, 1, 1).data)
        .slice(0, 3)
        .map((channel) => channel / 255);
    });
  };

  const resize = () => {
    if (disposed || gl.isContextLost()) return false;
    const bounds = host.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5);
    const width = Math.max(1, bounds.width * dpr);
    const height = Math.max(1, bounds.height * dpr);
    const fit = Math.min(
      1,
      Math.sqrt(pixelBudget / (width * height)),
      maxDimension / width,
      maxDimension / height,
    );
    const nextWidth = Math.max(1, Math.floor(width * fit));
    const nextHeight = Math.max(1, Math.floor(height * fit));
    if (canvas.width === nextWidth && canvas.height === nextHeight)
      return false;
    canvas.width = nextWidth;
    canvas.height = nextHeight;
    gl.viewport(0, 0, nextWidth, nextHeight);
    return true;
  };

  const tick = (now: number) => {
    if (!running || disposed) return;
    frame = requestAnimationFrame(tick);
    if (gl.isContextLost()) return;
    phase += (Math.min(Math.max(0, now - lastTick), 100) / 1000) * config.speed;
    lastTick = now;
    if (lastDraw >= 0 && now - lastDraw < effectFrameInterval) return;
    // Space actual draws by at least 1/30s, including jitter and quick resumes.
    lastDraw = now;
    gl.useProgram(program);
    gl.bindVertexArray(vertexArray);
    gl.uniform2f(uniforms.uResolution, canvas.width, canvas.height);
    gl.uniform1f(uniforms.uTime, phase);
    gl.uniform1f(uniforms.uScale, config.scale);
    gl.uniform1f(uniforms.uIntensity, config.intensity);
    gl.uniform3fv(uniforms.uColorA, rgbColors[0]);
    gl.uniform3fv(uniforms.uColorB, rgbColors[1]);
    gl.uniform3fv(uniforms.uColorC, rgbColors[2]);
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    onFrame();
  };

  const stop = () => {
    running = false;
    if (frame) cancelAnimationFrame(frame);
    frame = 0;
  };

  try {
    configure(initial);
    resize();
  } catch (error) {
    gl.deleteVertexArray(vertexArray);
    gl.deleteProgram(program);
    colorCanvas.width = 0;
    colorCanvas.height = 0;
    throw error;
  }
  return {
    configure,
    resize,
    start() {
      if (running || disposed || gl.isContextLost()) return;
      running = true;
      lastTick = performance.now();
      frame = requestAnimationFrame(tick);
    },
    stop,
    dispose() {
      if (disposed) return;
      stop();
      disposed = true;
      if (!gl.isContextLost()) {
        gl.bindVertexArray(null);
        gl.useProgram(null);
        gl.deleteVertexArray(vertexArray);
        gl.deleteProgram(program);
        canvas.width = 1;
        canvas.height = 1;
      }
      // Do not force context loss: React Strict Mode can reuse this canvas.
      colorCanvas.width = 0;
      colorCanvas.height = 0;
    },
  };
}

import type { ShaderKind } from "./effect-utils";

/**
 * Original Aureform UI 1.1 procedural shaders. No textures, remote assets or
 * third-party shader code. This module is loaded only when a shader can run.
 * See docs/shaders.md for the uniform contract and GLSL -> WGSL port notes.
 */
export const shaderVertexSource = `#version 300 es
precision highp float;

void main() {
  vec2 corners[3] = vec2[3](
    vec2(-1.0, -1.0),
    vec2( 3.0, -1.0),
    vec2(-1.0,  3.0)
  );
  gl_Position = vec4(corners[gl_VertexID], 0.0, 1.0);
}
`;

export const shaderCommonSource = `#version 300 es
precision highp float;

uniform vec2 uResolution;
uniform float uTime;
uniform float uScale;
uniform float uIntensity;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
out vec4 fragColor;

float hash21(vec2 p) {
  vec3 q = fract(vec3(p.x, p.y, p.x) * 0.1031);
  q += dot(q, q.yzx + 33.33);
  return fract((q.x + q.y) * q.z);
}

float noise21(vec2 p) {
  vec2 cell = floor(p);
  vec2 f = fract(p);
  vec2 blend = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash21(cell), hash21(cell + vec2(1.0, 0.0)), blend.x),
    mix(hash21(cell + vec2(0.0, 1.0)), hash21(cell + vec2(1.0)), blend.x),
    blend.y
  );
}

float fbm(vec2 p) {
  float total = 0.0;
  float weight = 0.5;
  mat2 octave = mat2(1.67, 1.12, -1.12, 1.67);
  for (int i = 0; i < 4; i++) {
    total += noise21(p) * weight;
    p = octave * p + vec2(3.2, 7.1);
    weight *= 0.5;
  }
  return total;
}

vec3 spectrum(float phase) {
  vec3 weights = 0.5 + 0.5 * cos(vec3(0.0, 2.094395, 4.188790) + phase);
  weights *= weights;
  return (
    uColorA * weights.x + uColorB * weights.y + uColorC * weights.z
  ) / max(dot(weights, vec3(1.0)), 0.001);
}

vec2 scenePoint() {
  return (2.0 * gl_FragCoord.xy - uResolution)
    / max(min(uResolution.x, uResolution.y), 1.0) * uScale;
}

vec3 finishLight(vec3 light, vec2 uv) {
  vec3 ink = vec3(0.018, 0.023, 0.052);
  float vignette = 1.0 - 0.36 * smoothstep(
    0.18, 0.82, length((uv - 0.5) * vec2(1.04, 1.0))
  );
  vec3 color = (ink + max(light, vec3(0.0)) * uIntensity) * vignette;
  color = vec3(1.0) - exp(-color * 1.28);
  // Fixed spatial grain avoids temporal flicker and gradient banding.
  color += (hash21(gl_FragCoord.xy) - 0.5) * 0.008;
  return clamp(color, 0.0, 1.0);
}
`;

export const auroraFragmentSource =
  shaderCommonSource +
  `
void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  vec2 p = scenePoint();
  float t = uTime;
  p.x += 0.22 * p.y;
  vec3 light = vec3(0.0);

  for (int i = 0; i < 3; i++) {
    float lane = float(i);
    float turbulence = fbm(vec2(
      p.y * 0.62 + lane * 3.4 - t * 0.13,
      p.x * 0.38 + t * 0.09
    ));
    float center = -0.85 + lane * 0.94
      + 0.26 * sin(p.y * 1.35 + lane * 1.7 + t * 0.28)
      + (turbulence - 0.46) * 0.72;
    float distance = p.x - center;
    float curtain = exp(-distance * distance * (7.5 + lane * 2.0));
    float bloom = exp(-distance * distance * 1.7) * 0.16;
    float filament = pow(
      0.5 + 0.5 * sin(distance * 64.0 + turbulence * 9.0), 6.0
    );
    float drape = 0.58 + 0.42 * smoothstep(-1.5, 1.1, p.y);
    vec3 tint = spectrum(lane * 2.094395 + p.y * 0.3 + t * 0.09);
    light += tint * (curtain * (1.1 + filament * 0.32) + bloom) * drape;
  }

  light += spectrum(p.y * 0.7 + 1.4) * 0.13 * exp(-dot(p, p) * 0.16);
  fragColor = vec4(finishLight(light, uv), 1.0);
}
`;

export const wavesFragmentSource =
  shaderCommonSource +
  `
void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  vec2 p = scenePoint();
  float t = uTime;
  p.y += p.x * 0.16;
  vec3 light = vec3(0.0);

  for (int i = 0; i < 3; i++) {
    float lane = float(i);
    float swell = 0.28 * sin(p.x * 1.38 + lane * 0.9 + t * 0.32)
      + 0.13 * sin(p.x * 2.7 - lane * 1.15 - t * 0.23);
    float center = -0.62 + lane * 0.61 + swell;
    float distance = p.y - center;
    float ribbon = exp(-distance * distance * 17.0);
    float edgeDistance = abs(distance) - 0.14;
    float edge = exp(-edgeDistance * edgeDistance * 310.0);
    float engraving = pow(
      0.5 + 0.5 * cos(distance * 92.0 + p.x * 0.65), 16.0
    );
    vec3 tint = spectrum(lane * 2.094395 + p.x * 0.26 - t * 0.08);
    light += tint * (ribbon * 0.98 + edge * 0.28);
    light += mix(tint, vec3(0.82, 0.94, 1.0), 0.48)
      * engraving * ribbon * 0.12;
  }

  light += spectrum(p.x * 0.35 + 2.6) * 0.1
    * exp(-p.y * p.y * 0.45);
  fragColor = vec4(finishLight(light, uv), 1.0);
}
`;

export const iridescentFragmentSource =
  shaderCommonSource +
  `
void main() {
  vec2 uv = gl_FragCoord.xy / uResolution;
  vec2 p = scenePoint();
  float t = uTime;
  vec2 q = p + 0.24 * vec2(
    sin(p.y * 1.25 + t * 0.19),
    cos(p.x * 1.08 - t * 0.17)
  );
  float fold = q.x * 1.8 + 0.75 * sin(q.y * 1.1 + t * 0.17);
  float crossFold = q.y * 2.1 - q.x * 0.8 - t * 0.23;
  float height = sin(fold) + 0.52 * cos(crossFold);
  float dx = 1.8 * cos(fold) + 0.416 * sin(crossFold);
  float dy = 0.825 * cos(q.y * 1.1 + t * 0.17) * cos(fold)
    - 1.092 * sin(crossFold);
  vec3 normal = normalize(vec3(-dx * 0.46, -dy * 0.46, 1.0));
  vec3 keyLight = normalize(vec3(-0.35, 0.6, 0.85));
  float diffuse = max(dot(normal, keyLight), 0.0);
  float pearl = pow(
    max(dot(normal, normalize(vec3(0.25, -0.15, 1.0))), 0.0), 22.0
  );
  float fresnel = pow(1.0 - normal.z, 2.0);
  float contour = pow(
    0.5 + 0.5 * cos(height * 13.0 + p.x * 0.2), 22.0
  );
  vec3 tint = spectrum(height * 1.55 + p.x * 0.32 + t * 0.08);
  vec3 light = tint * (0.3 + diffuse * 0.86 + fresnel * 0.6)
    + vec3(0.78, 0.9, 1.0) * pearl * 0.62
    + mix(tint, vec3(0.9), 0.35) * contour * 0.06;
  fragColor = vec4(finishLight(light, uv), 1.0);
}
`;

export const shaderFragmentSources: Record<
  Exclude<ShaderKind, "none">,
  string
> = {
  aurora: auroraFragmentSource,
  waves: wavesFragmentSource,
  iridescent: iridescentFragmentSource,
};

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
export function downloadText(
  filename: string,
  text: string,
  type = "text/plain",
) {
  const url = URL.createObjectURL(new Blob([text], { type }));
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function csv(rows: Record<string, unknown>[]) {
  if (!rows.length) return "";
  const keys = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const raw = String(value ?? "");
    const safe = /^[=+@\t\r-]/.test(raw) ? `'${raw}` : raw;
    return `"${safe.replaceAll('"', '""')}"`;
  };
  return [
    keys.map(escape).join(","),
    ...rows.map((row) => keys.map((k) => escape(row[k])).join(",")),
  ].join("\r\n");
}
